#!/usr/bin/env python3
"""Exact finite polynomial-generator tests of fourth-order relaxation resonance."""
import sympy as s

def build(N,k=1,Dr=1,v=1):
    # Restrict to the invariant sector generated by H_N(x) from an angle-uniform observable.
    # H_j are monic thermal-OU Hermites. Angle basis cos(m theta), m >=0.
    basis=[(j,m) for j in range(N,-1,-1) for m in range(N-j+1) if (m-(N-j))%2==0]
    lookup={a:i for i,a in enumerate(basis)}
    A=s.zeros(len(basis))
    for i,(j,m) in enumerate(basis):
        A[i,i]=-j*k-m*m*Dr
        if j:
            if m==0:
                A[lookup[(j-1,1)],i]+=j*v
            else:
                A[lookup[(j-1,m-1)],i]+=s.Rational(j,2)*v
                A[lookup[(j-1,m+1)],i]+=s.Rational(j,2)*v
    return basis,A

def pole_order(A,e):
    zz=s.symbols('zz')
    # exact resolvent order by Jordan nilpotence ranks instead of numeric fitting
    alg=sum(A[i,i]==e for i in range(A.rows))
    geo=A.rows-(A-e*s.eye(A.rows)).rank()
    return alg,geo

for n in (1,2,3):
    B,A=build(n)
    for E in set(A.diagonal()):
        alg,_=pole_order(A,E)
        assert alg<=2, (n,E,alg)
B,A=build(4)
assert len(B)==9 and B[0]==(4,0)
assert [(j,m) for j,m in B if j+m*m==4]==[(4,0),(3,1),(0,2)]
assert pole_order(A,-4)==(3,1)
# The double-nilpotent coefficient is the cubic resolvent pole from H_4 to cos(2 theta).
z=s.symbols('z'); R=(z*s.eye(A.rows)-A).inv()
coefficient=s.limit((z+4)**3*R[B.index((0,2)),B.index((4,0))],z,-4)
assert coefficient==1,coefficient
# Independently sum the three distinct fourth-order transfer paths.
# Intermediate denominators are evaluated at the resonant eigenvalue -4*kappa.
hand=s.Rational(6,4)-s.Rational(3,4)+s.Rational(3,12)
assert hand==coefficient==1
# Non-unit parameters: r=Dr=k, activity v; heat D affects Hermite definition, not generator.
for kk,vv in [(s.Rational(2),s.Rational(3)),(s.Rational(3,2),s.Rational(5,3))]:
    B2,A2=build(4,k=kk,Dr=kk,v=vv)
    zz=s.symbols('zz')
    rr=(zz*s.eye(A2.rows)-A2).inv()
    val=s.limit((zz+4*kk)**3*rr[B2.index((0,2)),0],zz,-4*kk)
    assert s.simplify(val-vv**4/kk**2)==0,(kk,vv,val)
print('PASS: 9-state invariant block; eigenvalue -4 has algebraic multiplicity 3 and geometric multiplicity 1; exact cubic pole v^4/k^2; lower positional degrees at most double; two rational rescalings')
